package dev.spaceclient;
import dev.spaceclient.mods.*;
import dev.spaceclient.hud.*;
import java.io.*;import java.nio.file.*;import java.util.*;
import org.junit.*;import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;
public class ExpansionModsTest {
 @Rule public TemporaryFolder dir=new TemporaryFolder();
 private Path file(String n){return dir.getRoot().toPath().resolve(n);}
 private void fixture(String name,Path p)throws Exception{try(InputStream in=getClass().getResourceAsStream("/hud-legacy/"+name)){assertNotNull(in);Files.copy(in,p);}}
 @Test public void genuineSchemaNineKeepsOldModulesMessagesAndStylesWithoutRewriting()throws Exception{
  Path p=file("mods");fixture("mods-schema9-1af3562.properties",p);byte[] original=Files.readAllBytes(p);ModSettings s=ModSettings.open(p);assertFalse(s.isReadOnly());
  for(GameplayModule m:GameplayModule.values()){boolean old=m.ordinal()<GameplayModule.SCOREBOARD.ordinal();assertEquals(old,m.enabled(s));assertEquals(old?30+m.ordinal():0,s.toggleKey(m));}
  assertEquals("/fixture old",s.autoTextMessage(0));assertEquals(75,s.autoTextKey(0));assertEquals(3,s.guiScale());assertEquals(3,s.hitboxWidth());assertEquals(4,s.physicsSpeed());assertEquals(130,s.heldItemScale());assertEquals(40,s.soundsVolume());assertArrayEquals(original,Files.readAllBytes(p));
  assertTrue(s.toggleScoreboard());Properties out=new Properties();try(InputStream in=Files.newInputStream(p)){out.load(in);}assertEquals("10",out.getProperty("schemaVersion"));assertEquals(132,out.size());assertTrue(ModSettings.open(p).scoreboard());assertEquals("/fixture old",ModSettings.open(p).autoTextMessage(0));
 }
 @Test public void allEightSettingsAndToggleKeysRoundTripAndResetIndependently()throws Exception{
  ModSettings s=ModSettings.open(file("mods"));for(GameplayModule m:GameplayModule.values())if(m.ordinal()>=GameplayModule.SCOREBOARD.ordinal()){assertFalse(m.enabled(s));assertTrue(m.toggle(s));assertTrue(s.toggleKey(m,40+m.ordinal()));}
  s.scoreboardNumbers(true);s.scoreboardScale(130);s.scoreboardX(-40);s.tntDistance(96);s.tntColor(VisualPalette.RAINBOW);s.tooltipSpeed(18);s.waypointBeam(false);s.particleAmount(250);s.particleScale(175);s.particleTint(true);s.glintColor(VisualPalette.RED);s.glintSpeed(200);s.glintStrength(40);s.blurStrength(7);s.backgroundFps(10);s.idleFps(30);s.idleSeconds(20);
  s=ModSettings.open(file("mods"));assertFalse(s.isReadOnly());assertEquals(130,s.scoreboardScale());assertEquals(-40,s.scoreboardX());assertEquals(96,s.tntDistance());assertEquals(18,s.tooltipSpeed());assertFalse(s.waypointBeam());assertEquals(250,s.particleAmount());assertEquals(175,s.particleScale());assertTrue(s.particleTint());assertEquals(200,s.glintSpeed());assertEquals(7,s.blurStrength());assertEquals(10,s.backgroundFps());
  for(GameplayModule m:GameplayModule.values())if(m.ordinal()>=GameplayModule.SCOREBOARD.ordinal()){assertTrue(m.enabled(s));assertTrue(s.reset(m));assertTrue(m.enabled(s));assertEquals(0,s.toggleKey(m));}
  assertEquals(100,s.scoreboardScale());assertEquals(64,s.tntDistance());assertEquals(10,s.tooltipSpeed());assertTrue(s.waypointBeam());assertEquals(100,s.particleAmount());assertEquals(100,s.glintSpeed());assertEquals(4,s.blurStrength());assertEquals(30,s.backgroundFps());
 }
 @Test public void invalidSettingsAndFailedWritesRevertWithoutAffectingOldMods()throws Exception{
  ModSettings s=ModSettings.open(file("mods"));s.toggleZoom();byte[] original=Files.readAllBytes(file("mods"));assertFalse(s.scoreboardScale(0));assertFalse(s.tntDistance(129));assertFalse(s.particleAmount(301));assertFalse(s.glintColor(null));assertFalse(s.blurStrength(9));assertFalse(s.idleSeconds(0));assertArrayEquals(original,Files.readAllBytes(file("mods")));
  Files.createFile(file("blocked"));s=ModSettings.open(file("blocked/mods"));assertFalse(s.toggleDynamicFps());assertFalse(s.dynamicFps());assertEquals(30,s.backgroundFps());
 }
 @Test public void realHudSeventeenAndExportTwelveKeepLayoutsAndNewWidgetsOptIn()throws Exception{
  Path p=file("hud");fixture("hud-schema17-1af3562.properties",p);byte[] old=Files.readAllBytes(p);HudConfig h=HudConfig.load(p);assertEquals(17,h.migrationSourceVersion());assertTrue(h.active().inventory);assertEquals(13,h.active().placement(HudModule.INVENTORY).x,0);assertArrayEquals(old,Files.readAllBytes(p));
  for(HudModule m:new HudModule[]{HudModule.COMBO_COUNTER,HudModule.REACH_DISPLAY,HudModule.SATURATION}){assertFalse(m.isEnabled(h));m.setEnabled(h,true);assertFalse(m.isEnabled(new HudConfig()));}
  h.save(p);h=HudConfig.load(p);assertEquals(0,h.migrationSourceVersion());assertTrue(h.active().combo);assertTrue(h.active().reach);assertTrue(h.active().saturation);assertFalse(h.profile(1).combo);
  Path export=file("export");fixture("profile-export12-1af3562.properties",export);HudProfile imported=HudConfig.importProfile(export);assertTrue(imported.inventory);assertFalse(imported.combo);assertEquals(1.25,imported.placement(HudModule.INVENTORY).scale,0);HudConfig.exportProfile(export,h.active());assertTrue(HudConfig.importProfile(export).saturation);
 }
 @Test public void comboNeedsRecentMatchingStatusDoesNotCountDuplicatesAndExpires(){CombatChain c=new CombatChain();long t=10_000_000_000L;c.attack(1,t);assertEquals(0,c.count(t));c.hurt(2,false,t);assertEquals(0,c.count(t));c.hurt(1,false,t+1);c.hurt(1,false,t+2);assertEquals(1,c.count(t+3));c.attack(1,t+4);c.hurt(1,false,t+5);assertEquals(2,c.count(t+6));c.hurt(3,true,t+7);assertEquals(0,c.count(t+8));c.attack(1,t+9);c.hurt(1,false,t+2_000_000_000L);assertEquals(0,c.count(t+2_000_000_000L));c.attack(1,t+3_000_000_000L);c.hurt(1,false,t+3_000_000_001L);assertEquals(0,c.count(t+6_000_000_000L));}
 @Test public void idlePolicyHonoursNativeCapDisabledRestoreAndActivity(){IdleFramePolicy p=new IdleFramePolicy();p.active(1_000_000_000L);assertEquals(144,p.limit(144,true,true,2_000_000_000L,30,60,10));assertEquals(60,p.limit(144,true,true,11_000_000_000L,30,60,10));assertEquals(30,p.limit(0,true,false,12_000_000_000L,30,60,10));assertEquals(15,p.limit(15,true,false,12_000_000_000L,30,60,10));assertEquals(144,p.limit(144,false,false,12_000_000_000L,30,60,10));p.active(12_000_000_000L);assertEquals(144,p.limit(144,true,true,12_000_000_001L,30,60,10));}
 @Test public void tooltipOffsetsClampAndHorizontalAndVerticalAreIndependent(){TooltipScroll s=new TooltipScroll();s.scroll(-120,false,10,300,600,100,100);assertEquals(10,s.y);assertEquals(0,s.x);for(int i=0;i<100;i++)s.scroll(-120,true,10,300,600,100,100);assertEquals(200,s.x);assertEquals(10,s.y);s.scroll(120,false,100,300,600,100,100);assertEquals(0,s.y);s.scroll(0,true,0,50,50,100,100);assertEquals(0,s.x);s.reset();assertEquals(0,s.y);}
 @Test public void waypointContextDimensionsPersistenceAndRemovalAreIndependent()throws Exception{String a=String.join("",Collections.nCopies(64,"a")),b=String.join("",Collections.nCopies(64,"b"));WaypointStore s=WaypointStore.open(file("points"));WaypointStore.Point p=new WaypointStore.Point(a,"Дом",0,5,70,-8,VisualPalette.AQUA,true);assertTrue(s.add(p));assertTrue(s.add(new WaypointStore.Point(a,"Nether",-1,3,40,5,VisualPalette.RED,false)));assertTrue(s.add(new WaypointStore.Point(b,"Other",0,4,40,8,VisualPalette.GOLD,true)));assertEquals(1,s.current(a,0).size());s=WaypointStore.open(file("points"));assertFalse(s.readOnly());p=s.current(a,0).get(0);assertEquals("Дом",p.name);assertTrue(s.replace(p,p.visible(false)));assertFalse(s.current(a,0).get(0).visible);assertTrue(s.replace(s.current(a,0).get(0),null));assertEquals(2,WaypointStore.open(file("points")).all().size());}
 @Test public void malformedFutureAndFailedWaypointWritesPreserveBytes()throws Exception{Path p=file("points");byte[] future="schemaVersion=2\ncount=0\n".getBytes("UTF-8");Files.write(p,future);WaypointStore s=WaypointStore.open(p);assertTrue(s.readOnly());assertFalse(s.add(new WaypointStore.Point(String.join("",Collections.nCopies(64,"a")),"Test",0,0,50,0,VisualPalette.GOLD,true)));assertArrayEquals(future,Files.readAllBytes(p));Files.createFile(file("blocked"));s=WaypointStore.open(file("blocked/points"));assertFalse(s.add(new WaypointStore.Point(String.join("",Collections.nCopies(64,"a")),"Test",0,0,50,0,VisualPalette.GOLD,true)));assertTrue(s.all().isEmpty());}
}
